from PIL import Image, UnidentifiedImageError

def safe_pil_loader(path):
    try:
        with open(path, 'rb') as f:
            img = Image.open(f)
            return img.convert('RGB')
    except (UnidentifiedImageError, IOError, OSError) as e:
        print(f"Skipping corrupted image: {path}")
        raise e

train_transform = transforms.Compose([
    transforms.ToTensor(),
    transforms.Normalize((0.5,), (0.5,)),
])

# Create a dataset with a custom loader that handles corrupted images
class SafeImageFolder(datasets.ImageFolder):
    def __init__(self, root, transform=None, loader=None):
        super().__init__(root, transform=transform, loader=loader)
        # Filter out corrupted samples by trying to load them
        valid_samples = []
        for path, class_idx in self.samples:
            try:
                if self.loader is None:
                    self.loader = safe_pil_loader
                self.loader(path)
                valid_samples.append((path, class_idx))
            except (UnidentifiedImageError, IOError, OSError):
                continue
        self.samples = valid_samples
        print(f"Loaded {len(valid_samples)} valid images (skipped corrupted ones)")

train_dataset = SafeImageFolder(root='data_small/eyes data', transform=train_transform, loader=safe_pil_loader)
dataloader = torch.utils.data.DataLoader(dataset=train_dataset, batch_size=batch_size, shuffle=True)"}

